import Foundation

/// The solver parity corpus published by the `color_matching` backend.
///
/// The corpus is generated by the server's own solver
/// (`ColorMatching.WeightedSquaredError` plus the earliest-wins selection of
/// `ColorMatching.IlluminantMatching`) and committed upstream at
/// `priv/parity/v1/corpus.json`. Replaying it here is what keeps the mirrored
/// `WeightedSquaredErrorScorer` honest: tie-breaking, missing-measurement
/// exclusion, and channel weighting cannot drift apart silently.
struct ParityCorpus: Decodable {
    /// Version of the coupled scorer/selection semantics the corpus captures.
    let algorithmVersion: Int
    /// The server module that produced the expected results.
    let scorer: String
    /// The selection policy the corpus encodes (earliest index wins).
    let selection: String
    /// The missing-measurement policy the corpus encodes.
    let missingPolicy: String
    /// The light sources the corpus knows about.
    let lightSources: [String]
    /// The replayable scenarios.
    let scenarios: [ParityScenario]

    enum CodingKeys: String, CodingKey {
        case algorithmVersion = "algorithm_version"
        case scorer
        case selection
        case missingPolicy = "missing_policy"
        case lightSources = "light_sources"
        case scenarios
    }
}

/// One scenario: a target response vector, a palette of candidates, the
/// per-channel weights, and the server's expected outcome.
struct ParityScenario: Decodable {
    let id: String
    let summary: String
    /// Weights per light source. A source the app cannot measure (or does not
    /// know) is present here and must be ignored.
    let weights: [String: Double]
    let target: ParityEntry
    let palette: [ParityEntry]
    let expected: ParityExpectation

    enum CodingKeys: String, CodingKey {
        case id
        case summary = "description"
        case weights
        case target
        case palette
        case expected
    }
}

/// A response vector: a hex color plus the measured brightness per light
/// source. A source with no measurement is simply absent from `channels`.
struct ParityEntry: Decodable {
    let index: Int?
    let hexColor: String
    let channels: [String: Double]

    enum CodingKeys: String, CodingKey {
        case index
        case hexColor = "hex_color"
        case channels
    }
}

/// The server's expected outcome for one scenario.
struct ParityExpectation: Decodable {
    /// Per-candidate scores, in palette order.
    let scores: [ParityScore]
    /// The winning palette index, or `nil` when every candidate was excluded.
    let selectedIndex: Int?
    let selectedHexColor: String?
    /// The winning score, or `nil` when no candidate was selectable.
    let error: Double?
    /// Whether the selection was decided by a tie, or `nil` when there was no
    /// selection at all.
    let tieBroke: Bool?
    /// Every candidate that tied for the best score.
    let tiedIndices: [Int]

    enum CodingKeys: String, CodingKey {
        case scores
        case selectedIndex = "selected_index"
        case selectedHexColor = "selected_hex_color"
        case error
        case tieBroke = "tie_broke"
        case tiedIndices = "tied_indices"
    }
}

/// One candidate's expected score.
struct ParityScore: Decodable {
    let index: Int
    let score: ParityScoreValue

    enum CodingKeys: String, CodingKey {
        case index
        case score
    }
}

/// A candidate's expected score: either a number or the `"excluded"` marker
/// the server emits for candidates that cannot be ranked.
enum ParityScoreValue: Decodable, Equatable {
    case excluded
    case value(Double)

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let marker = try? container.decode(String.self) {
            guard marker == "excluded" else {
                throw DecodingError.dataCorruptedError(
                    in: container,
                    debugDescription: "Unknown score marker \"\(marker)\""
                )
            }
            self = .excluded
            return
        }
        self = .value(try container.decode(Double.self))
    }
}

/// The committed copy of the upstream parity corpus.
enum ParityCorpusFixture {
    /// Location of the corpus, relative to the test target directory.
    static let relativePath = "Fixtures/parity/v1/corpus.json"

    /// Fingerprint of the committed corpus (see ``fingerprint(of:)``).
    ///
    /// The corpus is refreshed from the upstream repository on purpose, so
    /// this pins the committed bytes to the artifact they were copied from and
    /// turns an accidental edit into a failing test.
    static let expectedFingerprint = "d29f7eebb0aa8010"

    /// The committed corpus file.
    static func fileURL() throws -> URL {
        guard let url = TestFixtureLocator.locate(relativePath) else {
            throw CorpusFixtureError.missing(relativePath: relativePath)
        }
        return url
    }

    /// Decodes the committed corpus.
    static func load() throws -> ParityCorpus {
        let data = try Data(contentsOf: try fileURL())
        return try JSONDecoder().decode(ParityCorpus.self, from: data)
    }

    /// A 64-bit FNV-1a fingerprint of the corpus bytes, with line endings
    /// normalized so a checkout with CRLF endings still matches.
    ///
    /// This is a drift detector, not a security hash: it only has to notice
    /// that the committed corpus changed.
    static func fingerprint(of data: Data) -> String {
        var hash: UInt64 = 0xcbf2_9ce4_8422_2325
        for byte in normalizedBytes(data) {
            hash ^= UInt64(byte)
            hash = hash &* 0x0000_0100_0000_01b3
        }
        let digits = String(hash, radix: 16)
        return String(repeating: "0", count: max(0, 16 - digits.count)) + digits
    }

    /// The corpus bytes with CRLF line endings normalized to LF.
    static func normalizedBytes(_ data: Data) -> [UInt8] {
        var bytes: [UInt8] = []
        bytes.reserveCapacity(data.count)
        var index = data.startIndex
        while index < data.endIndex {
            let byte = data[index]
            if byte == 0x0D {
                let next = data.index(after: index)
                if next < data.endIndex, data[next] == 0x0A {
                    bytes.append(0x0A)
                    index = data.index(after: next)
                    continue
                }
            }
            bytes.append(byte)
            index = data.index(after: index)
        }
        return bytes
    }

    /// Raised when the committed corpus cannot be found.
    enum CorpusFixtureError: Error, CustomStringConvertible {
        case missing(relativePath: String)

        var description: String {
            switch self {
            case .missing(let relativePath):
                return "The parity corpus fixture \"\(relativePath)\" is missing from the test target."
            }
        }
    }
}
